import java.util.Scanner;

public class Main {
    static long[] arr = new long[20];

    static long findMinCost(long n) {
        if (n == 0) return 0;
        int position = 0;
        for (int i = 1; i <= 16; ++i) {
            if (arr[i] > n) {
                position = i;
                break;
            }
        }
        long costOption1 = (long) 1e18, costOption2 = (long) 1e18;
        costOption1 = (n / arr[position - 1]) * (position - 1) + findMinCost(n % arr[position - 1]);
        if (arr[position] - n < n)
            costOption2 = position + findMinCost(arr[position] - n);
        return Math.min(costOption1, costOption2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        for (int i = 1; i <= 16; ++i)
            arr[i] = arr[i - 1] * 10 + 1;
        long inputNumber = scanner.nextLong();
        System.out.println(findMinCost(inputNumber));
        scanner.close();
    }
}
